#include <vector>
#include <cmath>

using namespace std;

class Solution {
public:
    vector<int> res;

    void dfs(int num, int n, int k) {
        if (n == 0) {
            res.push_back(num);
            return;
        }

        int last = num % 10;
        if (last + k < 10)
            dfs(num * 10 + last + k, n - 1, k);
        if (k != 0 && last - k >= 0)
            dfs(num * 10 + last - k, n - 1, k);
    }

    vector<int> numsSameConsecDiff(int n, int k) {
        for (int i = 1; i <= 9; ++i)
            dfs(i, n - 1, k);
        return res;
    }
};
